import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`learn-finance`,heroTitle:`Master your finances in minutes`,heroSubtitle:`Perplexity Computer analyzes your accounts, finds savings opportunities, and teaches you the why behind every move — automatically.`,inputUrlCta:`Get started`,inputUrlPlaceholder:`Current financial goal`,inputUrlPrefill:`Connect my accounts and teach me personal finance using my real numbers. The thing I most want is {url} — but ask me more questions to find my other blind spots. Then optimize my finances and teach me along the way. 1) Analyze my full financial picture and identify areas where I’m leaving money on the table. 2) Rank every finding by dollar impact and explain each one in plain language. 3) For each recommendation, teach me the underlying concept — why it works, not just what to do. 4) Apply fixes where possible and show me the before-and-after impact. 5) Build me a personalized learning path so I keep getting smarter about my money over time. Ask me how deep I want to go — quick wins only, or full financial education.`,heroOverlaySteps:[`Reviewing your financial goals and current account details`,`Analyzing spending patterns, debt structure, and savings rate`,`Identifying optimization opportunities across budgeting, investing, and taxes`,`Personalized action plan with plain-English explanations — ready to follow`],generatingSteps:[`Gathering your financial goals and account context to scope the analysis`,`Designing an agent to analyze your spending, savings, and debt for optimization opportunities`,`Configuring personalized recommendations with educational breakdowns for each suggestion`,`Setting up dashboards for budget tracking, goal progress, and financial health scoring`],featureSectionTitle:`From confusion to clarity`,featureCardTitles:[`Connects to your financial stack`,`Outputs you can act on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Mint, Google Sheets, Excel, Notion — Computer plugs into your tools so budgets, trackers, and plans stay in sync across one workflow.`,`Monthly budget breakdowns. Debt payoff timelines. Investment allocation suggestions. Tax-saving checklists. Computer delivers plans with the reasoning behind every recommendation.`],capabilitySectionTitle:`Your financial advisor, on autopilot`,capabilitySectionSubtitle:`Share your goals, step away, come back to a clear financial roadmap.`,capabilityCards:[{title:`Spending Analysis`,description:`Computer can categorize your expenses, flag unnecessary subscriptions, and show exactly where your money goes — with benchmarks against recommended targets.`},{title:`Debt Strategy`,description:`Computer can compare avalanche vs. snowball methods for your specific debts and build a payoff timeline — explaining the math behind the best approach.`},{title:`Savings & Investing`,description:`Computer can evaluate your emergency fund, retirement contributions, and investment mix — then suggest adjustments with plain-English explanations of why they matter.`},{title:`Connect Your Tools`,description:`Computer can read from Google Sheets, Excel, Notion, and more — build workflows that pull your financial data into one unified view.`},{title:`Remember & Learn`,description:`Computer can remember your income, goals, risk tolerance, and progress across sessions — so every recommendation builds on your full financial picture.`},{title:`Monitor & Alert`,description:`Computer can watch your spending categories and savings rate weekly — and ping you when you’re off track or a new opportunity appears.`}]});export{t as default};
